with filtered as (select *, upper(location) as location_upper from departments where dept_name != 'HR') select *, row_number() over w_recent as row_seq, last_value(location, true) over (partition by location order by budget, id rows between unbounded preceding and current row) as last_known_location, row_number() over (partition by location order by budget, id) as row_seq_2 from filtered window w_recent as (order by budget desc, id);
